import Foundation
import MongoKitten

/// Where countries rows are kept. Services depend only on this protocol.
public protocol CountryRepository: Sendable {
    /// The row with this primary key, or nil.
    func findByDocumentId(_ documentId: String) async throws -> Country?

    /// At most limit rows after the key after (nil for the first page), by primary key, and the key to read the next page from.
    func list(after: String?, limit: Int) async throws -> CursorPage<Country, String>

    /// The row with this id, or nil.
    func findById(_ id: Double) async throws -> Country?

    /// Stores a new row; the values the database fills are read back.
    @discardableResult
    func insert(_ entity: Country) async throws -> Country

    /// Stores the changes made to a row.
    @discardableResult
    func update(_ entity: Country) async throws -> Country

    /// Removes a row.
    func delete(_ entity: Country) async throws
}

/// Keeps countries rows in the database, through MongoKitten: on the database of the unit of work, or on its transaction.
public struct MongoCountryRepository: CountryRepository {
    let database: Db

    public init(db: Db) {
        self.database = db
    }

    public func findByDocumentId(_ documentId: String) async throws -> Country? {
        let documentFilter: BsonDocument = ["_id": try Bson.ofText(documentId)]
        return try await database.find("countries", documentFilter, limit: 1).first.map(Country.from)
    }

    public func list(after: String?, limit: Int) async throws -> CursorPage<Country, String> {
        var documentFilter: BsonDocument = [:]
        if let after { documentFilter["_id"] = ["$gt": try Bson.ofText(after)] as BsonDocument }
        let rows = try await database.find("countries", documentFilter, sort: ["_id": 1], limit: limit + 1).map(Country.from)
        let items = Array(rows.prefix(limit))
        return CursorPage(items: items, next: rows.count > limit ? items.last?.documentId : nil)
    }

    public func findById(_ id: Double) async throws -> Country? {
        let documentFilter: BsonDocument = ["id": try Bson.ofDouble(id)]
        return try await database.find("countries", documentFilter, limit: 1).first.map(Country.from)
    }

    @discardableResult
    public func insert(_ entity: Country) async throws -> Country {
        var entity = entity
        let document = try entity.toDocument()
        try await write { try await database.insert("countries", document) }
        entity.loadedDocument = Loaded(document: document)
        return entity
    }

    @discardableResult
    public func update(_ entity: Country) async throws -> Country {
        var entity = entity
        let now = try entity.toDocument()
        let fields = ["id", "name"]
        let changes = Bson.changes(entity.loadedDocument.document, now, fields)
        if !changes.isEmpty, let id = now["_id"] {
            try await write { try await database.update("countries", ["_id": id], changes) }
        }
        entity.loadedDocument = Loaded(document: now)
        return entity
    }

    public func delete(_ entity: Country) async throws {
        let documentFilter: BsonDocument = ["_id": try Bson.ofText(entity.documentId!)]
        try await write { try await database.delete("countries", documentFilter) }
    }

    /// Runs a write; a database refusal (a unique value, a row still pointed to) becomes a conflict.
    private func write<T>(_ work: () async throws -> T) async throws -> T {
        do {
            return try await work()
        } catch let error where isRefusal(error) {
            throw DomainError.conflict(entity: "Country", reason: "the database refused the change: \(error)", fields: [])
        }
    }
}

/// Keeps countries rows in memory, for tests and for trying the services without a database.
public final class MemoryCountryRepository: CountryRepository {
    private let rows = MemoryRows<Country>()

    public init() {}

    /// The rows reads see, by primary key.
    private func visible() async -> [Country] {
        await rows.all.sorted(by: isBefore)
    }

    public func findByDocumentId(_ documentId: String) async throws -> Country? {
