/// The values a create or an update gives, by field: nil when not given, .some(nil) when given empty.
fileprivate struct Values: Sendable {
    var documentId: String?? = nil
    var id: Double?? = nil
    var name: String?? = nil
}

/// Checks the values against the rules of the "countries" table, and the rows they point to; throws validationFailed with every problem.
fileprivate func validate(_ uow: any UnitOfWork, _ values: Values, _ current: Country?) async throws {
    let creating = current == nil
    var errors: [FieldError] = []
    if values.documentId ?? nil == nil && (creating || values.documentId != nil) {
        errors.append(FieldError("_id", "is required"))
    }
    if values.id ?? nil == nil && (creating || values.id != nil) {
        errors.append(FieldError("id", "is required"))
    }
    if values.name ?? nil == nil && (creating || values.name != nil) {
        errors.append(FieldError("name", "is required"))
    }
    if !errors.isEmpty { throw DomainError.validationFailed(entity: "Country", errors: errors) }
}

/// Values that must be unique are not taken by another row.
fileprivate func checkUnique(_ uow: any UnitOfWork, _ values: Values, _ current: Country?) async throws {
    if let id = values.id ?? current?.id,
       let other = try await uow.countries.findById(id),
       current.map({ other.documentId != $0.documentId }) ?? true {
        throw DomainError.conflict(entity: "Country", reason: "id is already taken", fields: ["id"])
    }
}

/// Every check before a write: the values, the rows they point to, the unique values.
fileprivate func checkValues(_ uow: any UnitOfWork, _ values: Values, _ current: Country?) async throws {
    try await validate(uow, values, current)
    try await checkUnique(uow, values, current)
}

/// Sets the given values on the entity.
fileprivate func applyValues(_ entity: inout Country, _ values: Values) {
    if let value = values.documentId { entity.documentId = value }
    if let value = values.id { entity.id = value }
    if let value = values.name { entity.name = value }
}

/// The values an update gives, by field.
fileprivate func given(_ changes: CountryUpdate) -> Values {
    Values(id: changes.id.given, name: changes.name.given)
}

/// The Country with this key; notFound when there is none.
fileprivate func find(_ uow: any UnitOfWork, _ documentId: String) async throws -> Country {
    guard let row = try await uow.countries.findByDocumentId(documentId) else {
        throw DomainError.notFound(entity: "Country", key: "\(documentId)")
    }
    return row
}

/// The Country as services return it.
fileprivate func read(_ entity: Country) -> CountryRead {
    CountryRead(documentId: entity.documentId!, id: entity.id!, name: entity.name!)
}

