/// Where customers rows are kept. Services depend only on this protocol.
public protocol CustomerRepository: Sendable {
    /// The row with this primary key, or nil.
    func findById(_ id: String) async throws -> Customer?

    /// At most limit rows after the key after (nil for the first page), by primary key, and the key to read the next page from.
    func list(after: String?, limit: Int) async throws -> CursorPage<Customer, String>

    /// The row with this email, or nil.
    func findByEmail(_ email: String) async throws -> Customer?

    /// Stores a new row; the values the database fills are read back.
    @discardableResult
    func insert(_ entity: Customer) async throws -> Customer

    /// Stores the changes made to a row.
    @discardableResult
    func update(_ entity: Customer) async throws -> Customer

    /// Removes a row.
    func delete(_ entity: Customer) async throws

    /// Adds an item to tags, and gives the row as it is then, if there is one.
    func addTag(_ id: String, _ tag: String) async throws -> Customer?

    /// Removes an item from tags, and gives the row as it is then, if there is one.
    func removeTag(_ id: String, _ tag: String) async throws -> Customer?
}

/// Keeps customers rows in the database, through MongoKitten: on the database of the unit of work, or on its transaction.
public struct MongoCustomerRepository: CustomerRepository {
    let database: Db

    public init(db: Db) {
        self.database = db
    }

    public func findById(_ id: String) async throws -> Customer? {
        guard Bson.isObjectId(id) else { return nil }
        let documentFilter: BsonDocument = ["_id": try Bson.ofObjectId(id), "deletedAt": Bson.null]
        return try await database.find("customers", documentFilter, limit: 1).first.map(Customer.from)
    }

    public func list(after: String?, limit: Int) async throws -> CursorPage<Customer, String> {
        var documentFilter: BsonDocument = ["deletedAt": Bson.null]
        if let after { documentFilter["_id"] = ["$gt": try Bson.ofObjectId(after)] as BsonDocument }
        let rows = try await database.find("customers", documentFilter, sort: ["_id": 1], limit: limit + 1).map(Customer.from)
        let items = Array(rows.prefix(limit))
        return CursorPage(items: items, next: rows.count > limit ? items.last?.id : nil)
    }

    public func findByEmail(_ email: String) async throws -> Customer? {
        let documentFilter: BsonDocument = ["email": try Bson.ofText(email), "deletedAt": Bson.null]
        return try await database.find("customers", documentFilter, limit: 1).first.map(Customer.from)
    }

    @discardableResult
    public func insert(_ entity: Customer) async throws -> Customer {
        var entity = entity
        entity.id = entity.id ?? Bson.newId()
        entity.active = entity.active ?? true
        entity.level = entity.level ?? "basic"
        entity.createdAt = entity.createdAt ?? Date()
        entity.updatedAt = entity.updatedAt ?? Date()
        let document = try entity.toDocument()
        try await write { try await database.insert("customers", document) }
        entity.loadedDocument = Loaded(document: document)
        return entity
    }

    @discardableResult
    public func update(_ entity: Customer) async throws -> Customer {
        var entity = entity
        entity.updatedAt = Date()
        let now = try entity.toDocument()
        let fields = ["email", "name", "passwordHash", "active", "level", "address", "tags", "preferences", "extra", "deletedAt"]
        let changes = Bson.changes(entity.loadedDocument.document, now, fields)
        if !changes.isEmpty, let id = now["_id"] {
            let stamped = Bson.alsoSet(changes, now, ["updatedAt"])
            try await write { try await database.update("customers", ["_id": id], stamped) }
        }
        entity.loadedDocument = Loaded(document: now)
        return entity
    }

    public func delete(_ entity: Customer) async throws {
        let documentFilter: BsonDocument = ["_id": try Bson.ofObjectId(entity.id!)]
        try await write { try await database.delete("customers", documentFilter) }
    }

    public func addTag(_ id: String, _ tag: String) async throws -> Customer? {
        guard Bson.isObjectId(id) else { return nil }
        let change: BsonDocument = ["$push": ["tags": try Bson.ofText(tag)] as BsonDocument, "$set": ["updatedAt": try Bson.ofDate(Date())] as BsonDocument]
        let documentFilter: BsonDocument = ["_id": try Bson.ofObjectId(id), "deletedAt": Bson.null]
        return try await write { try await database.change("customers", documentFilter, change) }.map(Customer.from)
    }

    public func removeTag(_ id: String, _ tag: String) async throws -> Customer? {
        guard Bson.isObjectId(id) else { return nil }
        let change: BsonDocument = ["$pull": ["tags": try Bson.ofText(tag)] as BsonDocument, "$set": ["updatedAt": try Bson.ofDate(Date())] as BsonDocument]
        let documentFilter: BsonDocument = ["_id": try Bson.ofObjectId(id), "deletedAt": Bson.null]
        return try await write { try await database.change("customers", documentFilter, change) }.map(Customer.from)
    }

    /// Runs a write; a database refusal (a unique value, a row still pointed to) becomes a conflict.
    private func write<T>(_ work: () async throws -> T) async throws -> T {
        do {
            return try await work()
        } catch let error where isRefusal(error) {
            throw DomainError.conflict(entity: "Customer", reason: "the database refused the change: \(error)", fields: [])
        }
    }
}

