        await rows.remove { sameKey($0, entity) }
    }

    public func addTag(_ id: String, _ tag: String) async throws -> Customer? {
        guard var found = await visible().first(where: { $0.id == id }) else { return nil }
        found.tags = (found.tags ?? []) + [tag]
        found.updatedAt = Date()
        let row = found
        await rows.store(row) { sameKey($0, row) }
        return row
    }

    public func removeTag(_ id: String, _ tag: String) async throws -> Customer? {
        guard var found = await visible().first(where: { $0.id == id }) else { return nil }
        found.tags?.removeAll { $0 == tag }
        found.updatedAt = Date()
        let row = found
        await rows.store(row) { sameKey($0, row) }
        return row
    }
