            var current = try await find(uow, id)
            if !(try await uow.orders.listByCustomer(current.id!)).isEmpty {
                throw DomainError.conflict(entity: "Customer", reason: "rows of orders still point to it", fields: ["orders"])
            }
            current.deletedAt = Date()
