    var extra: BsonValue?? = nil
    var deletedAt: Date?? = nil
    var updatedAt: Date?? = nil
}

/// Checks the values against the rules of the "customers" table, and the rows they point to; throws validationFailed with every problem.
fileprivate func validate(_ uow: any UnitOfWork, _ values: Values, _ current: Customer?) async throws {
    let creating = current == nil
    var errors: [FieldError] = []
    if let value = values.email ?? nil {
        if value.count > 120 {
            errors.append(FieldError("email", "is longer than 120 characters"))
        }
    } else if creating || values.email != nil {
        errors.append(FieldError("email", "is required"))
    }
    if let value = values.name ?? nil {
        if !(value.count >= 2) {
            errors.append(FieldError("name", "must have >= 2 characters"))
        }
    } else if creating || values.name != nil {
        errors.append(FieldError("name", "is required"))
    }
    if let value = values.level ?? nil {
        if !["basic", "gold"].contains(value) {
            errors.append(FieldError("level", "must be one of: basic, gold"))
        }
    }
    if let value = values.address ?? nil {
        checkCustomerAddress(value, "address", &errors)
    }
    if let value = values.preferences ?? nil {
        checkCustomerPreferences(value, "preferences", &errors)
    }
    if !errors.isEmpty { throw DomainError.validationFailed(entity: "Customer", errors: errors) }
}

/// Values that must be unique are not taken by another row.
fileprivate func checkUnique(_ uow: any UnitOfWork, _ values: Values, _ current: Customer?) async throws {
    if let email = values.email ?? current?.email,
       let other = try await uow.customers.findByEmail(email),
       current.map({ other.id != $0.id }) ?? true {
        throw DomainError.conflict(entity: "Customer", reason: "email is already taken", fields: ["email"])
    }
}

/// Every check before a write: the values, the rows they point to, the unique values.
fileprivate func checkValues(_ uow: any UnitOfWork, _ values: Values, _ current: Customer?) async throws {
    try await validate(uow, values, current)
    try await checkUnique(uow, values, current)
}

/// Sets the given values on the entity.
fileprivate func applyValues(_ entity: inout Customer, _ values: Values) {
    if let value = values.email { entity.email = value }
    if let value = values.name { entity.name = value }
    if let value = values.passwordHash { entity.passwordHash = value }
    if let value = values.active { entity.active = value }
    if let value = values.level { entity.level = value }
    if let value = values.address { entity.address = value }
    if let value = values.tags { entity.tags = value }
    if let value = values.preferences { entity.preferences = value }
    if let value = values.extra { entity.extra = value }
    if let value = values.deletedAt { entity.deletedAt = value }
    if let value = values.updatedAt { entity.updatedAt = value }
}

/// What a Customer.Address does not follow of its rules, each with the path of its field.
fileprivate func checkCustomerAddress(_ value: Customer.Address, _ path: String, _ errors: inout [FieldError]) {
    if value.street == nil { errors.append(FieldError("\(path).street", "is required")) }
    if value.city == nil { errors.append(FieldError("\(path).city", "is required")) }
    if let held = value.location {
        checkCustomerAddressLocation(held, "\(path).location", &errors)
    }
}

/// What a Customer.Address.Location does not follow of its rules, each with the path of its field.
fileprivate func checkCustomerAddressLocation(_ value: Customer.Address.Location, _ path: String, _ errors: inout [FieldError]) {
    if let held = value.type {
        if !["Point"].contains(held) {
            errors.append(FieldError("\(path).type", "must be one of: Point"))
        }
    }
}

/// What a Customer.Preferences does not follow of its rules, each with the path of its field.
fileprivate func checkCustomerPreferences(_ value: Customer.Preferences, _ path: String, _ errors: inout [FieldError]) {
}

/// The values an update gives, by field.
fileprivate func given(_ changes: CustomerUpdate) -> Values {
    Values(email: changes.email.given, name: changes.name.given, passwordHash: changes.passwordHash.given, active: changes.active.given, level: changes.level.given, address: changes.address.given, tags: changes.tags.given, preferences: changes.preferences.given, extra: changes.extra.given, deletedAt: changes.deletedAt.given, updatedAt: changes.updatedAt.given)
}

/// The Customer with this key; notFound when there is none.
fileprivate func find(_ uow: any UnitOfWork, _ id: String) async throws -> Customer {
    guard let row = try await uow.customers.findById(id) else {
        throw DomainError.notFound(entity: "Customer", key: "\(id)")
    }
    return row
}

/// The Customer as services return it.
fileprivate func read(_ entity: Customer) -> CustomerRead {
    CustomerRead(id: entity.id!, email: entity.email!, name: entity.name!, active: entity.active, level: entity.level, address: entity.address, tags: entity.tags, preferences: entity.preferences, extra: entity.extra, deletedAt: entity.deletedAt, createdAt: entity.createdAt, updatedAt: entity.updatedAt)
}

/// What is wrong with one field.
public struct FieldError: Sendable, Equatable {
    public let field: String
    public let message: String

    public init(_ field: String, _ message: String) {
        self.field = field
        self.message = message
    }
}

/// Every error a service throws on purpose. They carry no HTTP codes: whoever calls the services translates them.
public enum DomainError: Error, Sendable, Equatable, CustomStringConvertible {
    /// No row has this key.
    case notFound(entity: String, key: String)
    /// The change clashes with what is stored: a unique value, a newer version, rows that depend on it.
    case conflict(entity: String, reason: String, fields: [String])
    /// The values break the rules of the table: missing, too long, out of range, pointing nowhere.
    case validationFailed(entity: String, errors: [FieldError])

    public var description: String {
        switch self {
        case .notFound(let entity, let key): "No \(entity) has the key \(key)"
        case .conflict(let entity, let reason, _): "\(entity): \(reason)"
        case .validationFailed(let entity, let errors):
            "\(entity): " + errors.map { "\($0.field): \($0.message)" }.joined(separator: "; ")
        }
    }

    /// The fields a validation refused.
    public var invalidFields: [String] {
        if case .validationFailed(_, let errors) = self { errors.map(\.field) } else { [] }
    }
}

