/// A document of the "orders" collection. A property stays nil until it is set or read.
public struct Order: Sendable, Equatable {
    public var id: String?
    public var number: Double?
    public var year: Double?
    public var customer: String?
    public var lines: [Order.Line]?
    public var notes: [Order.Note]?
    public var placedAt: Date?
    /// As it was read: a change writes only what differs
    var loadedDocument = Loaded()

    public init(id: String? = nil, number: Double? = nil, year: Double? = nil, customer: String? = nil, lines: [Order.Line]? = nil, notes: [Order.Note]? = nil, placedAt: Date? = nil) {
        self.id = id
        self.number = number
        self.year = year
        self.customer = customer
        self.lines = lines
        self.notes = notes
        self.placedAt = placedAt
    }

    /// Gives an identifier to the documents of its lists that have none: MongoDB numbers only whole documents.
    mutating func identifyItems() {
        lines = lines?.map { item in var item = item; item.id = item.id ?? Bson.newId(); return item }
        notes = notes?.map { item in var item = item; item.id = item.id ?? Bson.newId(); return item }
    }

    /// A nested document: it is stored with the one that holds it.
    public struct Line: Sendable, Equatable {
        public var id: String?
        public var product: String?
        public var quantity: Double?
        public var price: Decimal?
        public var status: String?

        public init(id: String? = nil, product: String? = nil, quantity: Double? = nil, price: Decimal? = nil, status: String? = nil) {
            self.id = id
            self.product = product
            self.quantity = quantity
            self.price = price
            self.status = status
        }
    }

    /// A nested document: it is stored with the one that holds it.
    public struct Note: Sendable, Equatable {
        public var id: String?
        public var text: String?
        public var at: Date?

        public init(id: String? = nil, text: String? = nil, at: Date? = nil) {
            self.id = id
            self.text = text
            self.at = at
        }
    }
}

extension Order: DocumentValue {
    /// What a document holds.
    static func from(_ document: BsonDocument) throws -> Order {
        var entity = Order(
            id: try Bson.read(document, "_id", Bson.asObjectId),
            number: try Bson.read(document, "number", Bson.asDouble),
            year: try Bson.read(document, "year", Bson.asDouble),
            customer: try Bson.read(document, "customer", Bson.asObjectId),
            lines: try Bson.read(document, "lines", Bson.asList(Bson.asNested(Order.Line.self))),
            notes: try Bson.read(document, "notes", Bson.asList(Bson.asNested(Order.Note.self))),
            placedAt: try Bson.read(document, "placedAt", Bson.asDate))
        entity.loadedDocument = Loaded(document: try entity.toDocument())
        return entity
    }

    /// Its document: what is nil is left out.
    func toDocument() throws -> BsonDocument {
        var document: BsonDocument = [:]
        try Bson.write(&document, "_id", self.id, Bson.ofObjectId)
        try Bson.write(&document, "number", self.number, Bson.ofDouble)
        try Bson.write(&document, "year", self.year, Bson.ofDouble)
        try Bson.write(&document, "customer", self.customer, Bson.ofObjectId)
        try Bson.write(&document, "lines", self.lines, Bson.ofList(Bson.ofNested))
        try Bson.write(&document, "notes", self.notes, Bson.ofList(Bson.ofNested))
        try Bson.write(&document, "placedAt", self.placedAt, Bson.ofDate)
        return document
    }
}

