/// Where orders rows are kept. Services depend only on this protocol.
public protocol OrderRepository: Sendable {
    /// The row with this primary key, or nil.
    func findById(_ id: String) async throws -> Order?

    /// At most limit rows after the key after (nil for the first page), by primary key, and the key to read the next page from.
    func list(after: String?, limit: Int) async throws -> CursorPage<Order, String>

    /// The row with this year and number, or nil.
    func findByYearAndNumber(_ year: Double, _ number: Double) async throws -> Order?

    /// Rows with this customer, by primary key.
    func listByCustomer(_ customer: String) async throws -> [Order]

    /// Stores a new row; the values the database fills are read back.
    @discardableResult
    func insert(_ entity: Order) async throws -> Order

    /// Stores the changes made to a row.
    @discardableResult
    func update(_ entity: Order) async throws -> Order

    /// Removes a row.
    func delete(_ entity: Order) async throws

    /// Adds an item to lines, and gives the row as it is then, if there is one.
    func addLine(_ id: String, _ line: Order.Line) async throws -> Order?

    /// Removes an item from lines, and gives the row as it is then, if there is one.
    func removeLine(_ id: String, _ lineId: String) async throws -> Order?

    /// Adds an item to notes, and gives the row as it is then, if there is one.
    func addNote(_ id: String, _ note: Order.Note) async throws -> Order?

    /// Removes an item from notes, and gives the row as it is then, if there is one.
    func removeNote(_ id: String, _ noteId: String) async throws -> Order?
}

/// Keeps orders rows in the database, through MongoKitten: on the database of the unit of work, or on its transaction.
public struct MongoOrderRepository: OrderRepository {
    let database: Db

    public init(db: Db) {
        self.database = db
    }

    public func findById(_ id: String) async throws -> Order? {
        guard Bson.isObjectId(id) else { return nil }
        let documentFilter: BsonDocument = ["_id": try Bson.ofObjectId(id)]
        return try await database.find("orders", documentFilter, limit: 1).first.map(Order.from)
    }

    public func list(after: String?, limit: Int) async throws -> CursorPage<Order, String> {
        var documentFilter: BsonDocument = [:]
        if let after { documentFilter["_id"] = ["$gt": try Bson.ofObjectId(after)] as BsonDocument }
        let rows = try await database.find("orders", documentFilter, sort: ["_id": 1], limit: limit + 1).map(Order.from)
        let items = Array(rows.prefix(limit))
        return CursorPage(items: items, next: rows.count > limit ? items.last?.id : nil)
    }

    public func findByYearAndNumber(_ year: Double, _ number: Double) async throws -> Order? {
        let documentFilter: BsonDocument = ["year": try Bson.ofDouble(year), "number": try Bson.ofDouble(number)]
        return try await database.find("orders", documentFilter, limit: 1).first.map(Order.from)
    }

    public func listByCustomer(_ customer: String) async throws -> [Order] {
        guard Bson.isObjectId(customer) else { return [] }
        let documentFilter: BsonDocument = ["customer": try Bson.ofObjectId(customer)]
        return try await database.find("orders", documentFilter, sort: ["_id": 1]).map(Order.from)
    }

    @discardableResult
    public func insert(_ entity: Order) async throws -> Order {
        var entity = entity
        entity.id = entity.id ?? Bson.newId()
        entity.placedAt = entity.placedAt ?? Date()
        entity.identifyItems()
        let document = try entity.toDocument()
        try await write { try await database.insert("orders", document) }
        entity.loadedDocument = Loaded(document: document)
        return entity
    }

    @discardableResult
    public func update(_ entity: Order) async throws -> Order {
        var entity = entity
        entity.identifyItems()
        let now = try entity.toDocument()
        let fields = ["number", "year", "customer", "lines", "notes"]
        let changes = Bson.changes(entity.loadedDocument.document, now, fields)
        if !changes.isEmpty, let id = now["_id"] {
            try await write { try await database.update("orders", ["_id": id], changes) }
        }
        entity.loadedDocument = Loaded(document: now)
        return entity
    }

    public func delete(_ entity: Order) async throws {
        let documentFilter: BsonDocument = ["_id": try Bson.ofObjectId(entity.id!)]
        try await write { try await database.delete("orders", documentFilter) }
    }

    public func addLine(_ id: String, _ line: Order.Line) async throws -> Order? {
        guard Bson.isObjectId(id) else { return nil }
        var line = line
        line.id = line.id ?? Bson.newId()
        let change: BsonDocument = ["$push": ["lines": try Bson.ofNested(line)] as BsonDocument]
        let documentFilter: BsonDocument = ["_id": try Bson.ofObjectId(id)]
        return try await write { try await database.change("orders", documentFilter, change) }.map(Order.from)
    }

    public func removeLine(_ id: String, _ lineId: String) async throws -> Order? {
        guard Bson.isObjectId(id) else { return nil }
        guard Bson.isObjectId(lineId) else { return nil }
        let change: BsonDocument = ["$pull": ["lines": ["_id": try Bson.ofObjectId(lineId)] as BsonDocument] as BsonDocument]
        let documentFilter: BsonDocument = ["_id": try Bson.ofObjectId(id)]
        return try await write { try await database.change("orders", documentFilter, change) }.map(Order.from)
    }

    public func addNote(_ id: String, _ note: Order.Note) async throws -> Order? {
        guard Bson.isObjectId(id) else { return nil }
        var note = note
        note.id = note.id ?? Bson.newId()
        let change: BsonDocument = ["$push": ["notes": try Bson.ofNested(note)] as BsonDocument]
        let documentFilter: BsonDocument = ["_id": try Bson.ofObjectId(id)]
        return try await write { try await database.change("orders", documentFilter, change) }.map(Order.from)
    }

    public func removeNote(_ id: String, _ noteId: String) async throws -> Order? {
        guard Bson.isObjectId(id) else { return nil }
        guard Bson.isObjectId(noteId) else { return nil }
        let change: BsonDocument = ["$pull": ["notes": ["_id": try Bson.ofObjectId(noteId)] as BsonDocument] as BsonDocument]
        let documentFilter: BsonDocument = ["_id": try Bson.ofObjectId(id)]
        return try await write { try await database.change("orders", documentFilter, change) }.map(Order.from)
    }

    /// Runs a write; a database refusal (a unique value, a row still pointed to) becomes a conflict.
    private func write<T>(_ work: () async throws -> T) async throws -> T {
        do {
            return try await work()
        } catch let error where isRefusal(error) {
            throw DomainError.conflict(entity: "Order", reason: "the database refused the change: \(error)", fields: [])
        }
    }
}

/// Keeps orders rows in memory, for tests and for trying the services without a database.
public final class MemoryOrderRepository: OrderRepository {
    private let rows = MemoryRows<Order>()

    public init() {}

    /// The rows reads see, by primary key.
    private func visible() async -> [Order] {
        await rows.all.sorted(by: isBefore)
    }

    public func findById(_ id: String) async throws -> Order? {
        await visible().first { $0.id == id }
    }

    public func list(after: String?, limit: Int) async throws -> CursorPage<Order, String> {
        let rows = await visible().filter { row in after.map { isAfter(row, $0) } ?? true }
        let items = Array(rows.prefix(limit))
        return CursorPage(items: items, next: rows.count > limit ? items.last.map { $0.id! } : nil)
    }

    public func findByYearAndNumber(_ year: Double, _ number: Double) async throws -> Order? {
        await visible().first { $0.year == year && $0.number == number }
    }

    public func listByCustomer(_ customer: String) async throws -> [Order] {
        await visible().filter { $0.customer == customer }
    }

    @discardableResult
    public func insert(_ entity: Order) async throws -> Order {
        var entity = entity
        entity.id = entity.id ?? Bson.newId()
        entity.placedAt = entity.placedAt ?? Date()
        entity.identifyItems()
        let row = entity
        await rows.store(row) { sameKey($0, row) }
        return row
    }

    @discardableResult
    public func update(_ entity: Order) async throws -> Order {
        var entity = entity
        entity.identifyItems()
        let row = entity
        await rows.store(row) { sameKey($0, row) }
        return row
    }

    public func delete(_ entity: Order) async throws {
        await rows.remove { sameKey($0, entity) }
    }

    public func addLine(_ id: String, _ line: Order.Line) async throws -> Order? {
        guard var found = await visible().first(where: { $0.id == id }) else { return nil }
        var line = line
        line.id = line.id ?? Bson.newId()
        found.lines = (found.lines ?? []) + [line]
        let row = found
        await rows.store(row) { sameKey($0, row) }
        return row
    }

    public func removeLine(_ id: String, _ lineId: String) async throws -> Order? {
        guard var found = await visible().first(where: { $0.id == id }) else { return nil }
        found.lines?.removeAll { $0.id == lineId }
        let row = found
        await rows.store(row) { sameKey($0, row) }
        return row
    }

    public func addNote(_ id: String, _ note: Order.Note) async throws -> Order? {
        guard var found = await visible().first(where: { $0.id == id }) else { return nil }
        var note = note
        note.id = note.id ?? Bson.newId()
        found.notes = (found.notes ?? []) + [note]
        let row = found
        await rows.store(row) { sameKey($0, row) }
        return row
    }

    public func removeNote(_ id: String, _ noteId: String) async throws -> Order? {
        guard var found = await visible().first(where: { $0.id == id }) else { return nil }
        found.notes?.removeAll { $0.id == noteId }
        let row = found
        await rows.store(row) { sameKey($0, row) }
        return row
    }
}

/// Whether two rows have the same key.
fileprivate func sameKey(_ a: Order, _ b: Order) -> Bool {
    a.id == b.id
}

/// Whether a row comes before another, by primary key.
fileprivate func isBefore(_ a: Order, _ b: Order) -> Bool {
    return less(a.id, b.id)
}

/// Whether a row comes after a key.
fileprivate func isAfter(_ row: Order, _ key: String) -> Bool {
    return less(key, row.id)
}

import Foundation

/// Operations on orders. Each write runs in its own transaction.
public struct OrderService: Sendable {
    private let unitOfWork: any UnitOfWork

    public init(unitOfWork: any UnitOfWork) {
        self.unitOfWork = unitOfWork
    }

    /// Stores a new Order after checking it.
    @discardableResult
    public func createOrder(_ data: OrderCreate) async throws -> OrderRead {
        let values = Values(number: data.number.map(Optional.some), year: data.year.map(Optional.some), customer: data.customer.map(Optional.some), lines: data.lines.map(Optional.some), notes: data.notes.map(Optional.some))
        return try await unitOfWork.transaction { uow in
            try await checkValues(uow, values, nil)
            var entity = Order()
            applyValues(&entity, values)
            return try await read(uow.orders.insert(entity))
        }
    }

    /// The Order with this key; notFound when there is none.
    public func getOrder(_ id: String) async throws -> OrderRead {
        try await read(find(unitOfWork, id))
    }

    /// A page of orders after the key after (nil for the first page), by primary key.
    public func listOrders(after: String?, limit: Int) async throws -> CursorPage<OrderRead, String> {
        try await unitOfWork.orders.list(after: after, limit: limit).map(read)
    }

    /// Changes the given values of a Order.
    @discardableResult
    public func updateOrder(_ id: String, _ changes: OrderUpdate) async throws -> OrderRead {
        let values = given(changes)
        return try await unitOfWork.transaction { uow in
            var current = try await find(uow, id)
            try await checkValues(uow, values, current)
            applyValues(&current, values)
            return try await read(uow.orders.update(current))
        }
    }

    /// Deletes a Order.
    public func deleteOrder(_ id: String) async throws {
        try await unitOfWork.transaction { uow in
            let current = try await find(uow, id)
            try await uow.orders.delete(current)
        }
    }

    /// The Order with this year and number, or nil.
    public func findOrderByYearAndNumber(_ year: Double, _ number: Double) async throws -> OrderRead? {
        try await unitOfWork.orders.findByYearAndNumber(year, number).map(read)
    }

    /// The orders with this customer.
    public func listOrdersByCustomer(_ customer: String) async throws -> [OrderRead] {
        try await unitOfWork.orders.listByCustomer(customer).map(read)
    }

    /// Adds an item to lines.
    @discardableResult
    public func addLine(_ id: String, _ line: Order.Line) async throws -> OrderRead {
        var errors: [FieldError] = []
        checkOrderLine(line, "lines", &errors)
        if !errors.isEmpty { throw DomainError.validationFailed(entity: "Order", errors: errors) }
        return try await unitOfWork.transaction { uow in
            _ = try await find(uow, id)
            guard let changed = try await uow.orders.addLine(id, line) else {
                throw DomainError.notFound(entity: "Order", key: "\(id)")
            }
            return read(changed)
        }
    }

    /// Removes an item from lines, by its identifier.
    @discardableResult
    public func removeLine(_ id: String, _ lineId: String) async throws -> OrderRead {
        return try await unitOfWork.transaction { uow in
            let current = try await find(uow, id)
            if !(current.lines ?? []).contains(where: { $0.id == lineId }) {
