/// Checks the values against the rules of the "orders" table, and the rows they point to; throws validationFailed with every problem.
fileprivate func validate(_ uow: any UnitOfWork, _ values: Values, _ current: Order?) async throws {
    let creating = current == nil
    var errors: [FieldError] = []
    if values.number ?? nil == nil && (creating || values.number != nil) {
