    }
    if values.customer ?? nil == nil && (creating || values.customer != nil) {
        errors.append(FieldError("customer", "is required"))
    }
    if let value = values.lines ?? nil {
        for (i0, item0) in value.enumerated() {
            checkOrderLine(item0, "lines.\(i0)", &errors)
        }
    } else if creating || values.lines != nil {
        errors.append(FieldError("lines", "is required"))
