/// Where products rows are kept. Services depend only on this protocol.
public protocol ProductRepository: Sendable {
    /// The row with this primary key, or nil.
    func findById(_ id: String) async throws -> Product?

    /// At most limit rows after the key after (nil for the first page), by primary key, and the key to read the next page from.
    func list(after: String?, limit: Int) async throws -> CursorPage<Product, String>

    /// The row with this sku, or nil.
    func findBySku(_ sku: String) async throws -> Product?

    /// Rows with this title, by primary key.
    func findAllByTitle(_ title: String) async throws -> [Product]

    /// Stores a new row; the values the database fills are read back.
    @discardableResult
    func insert(_ entity: Product) async throws -> Product

    /// Stores the changes made to a row.
    @discardableResult
    func update(_ entity: Product) async throws -> Product

    /// Removes a row.
    func delete(_ entity: Product) async throws

    /// Adds an item to related, and gives the row as it is then, if there is one.
    func addRelated(_ id: String, _ related: String) async throws -> Product?

    /// Removes an item from related, and gives the row as it is then, if there is one.
    func removeRelated(_ id: String, _ related: String) async throws -> Product?
}

/// Keeps products rows in the database, through MongoKitten: on the database of the unit of work, or on its transaction.
public struct MongoProductRepository: ProductRepository {
    let database: Db

    public init(db: Db) {
        self.database = db
    }

    public func findById(_ id: String) async throws -> Product? {
        guard Bson.isObjectId(id) else { return nil }
        let documentFilter: BsonDocument = ["_id": try Bson.ofObjectId(id)]
        return try await database.find("products", documentFilter, limit: 1).first.map(Product.from)
    }

    public func list(after: String?, limit: Int) async throws -> CursorPage<Product, String> {
        var documentFilter: BsonDocument = [:]
        if let after { documentFilter["_id"] = ["$gt": try Bson.ofObjectId(after)] as BsonDocument }
        let rows = try await database.find("products", documentFilter, sort: ["_id": 1], limit: limit + 1).map(Product.from)
        let items = Array(rows.prefix(limit))
        return CursorPage(items: items, next: rows.count > limit ? items.last?.id : nil)
    }

    public func findBySku(_ sku: String) async throws -> Product? {
        let documentFilter: BsonDocument = ["sku": try Bson.ofText(sku)]
        return try await database.find("products", documentFilter, limit: 1).first.map(Product.from)
    }

    public func findAllByTitle(_ title: String) async throws -> [Product] {
        let documentFilter: BsonDocument = ["title": try Bson.ofText(title)]
        return try await database.find("products", documentFilter, sort: ["_id": 1]).map(Product.from)
    }

    @discardableResult
    public func insert(_ entity: Product) async throws -> Product {
        var entity = entity
        entity.id = entity.id ?? Bson.newId()
        entity.stock = entity.stock ?? 0.0
        let document = try entity.toDocument()
        try await write { try await database.insert("products", document) }
        entity.loadedDocument = Loaded(document: document)
        return entity
    }

    @discardableResult
    public func update(_ entity: Product) async throws -> Product {
        var entity = entity
        let now = try entity.toDocument()
        let fields = ["sku", "title", "price", "stock", "reference", "picture", "related"]
        let changes = Bson.changes(entity.loadedDocument.document, now, fields)
        if !changes.isEmpty, let id = now["_id"] {
            try await write { try await database.update("products", ["_id": id], changes) }
        }
        entity.loadedDocument = Loaded(document: now)
        return entity
    }

    public func delete(_ entity: Product) async throws {
        let documentFilter: BsonDocument = ["_id": try Bson.ofObjectId(entity.id!)]
        try await write { try await database.delete("products", documentFilter) }
    }

    public func addRelated(_ id: String, _ related: String) async throws -> Product? {
        guard Bson.isObjectId(id) else { return nil }
        let change: BsonDocument = ["$push": ["related": try Bson.ofObjectId(related)] as BsonDocument]
        let documentFilter: BsonDocument = ["_id": try Bson.ofObjectId(id)]
        return try await write { try await database.change("products", documentFilter, change) }.map(Product.from)
    }

    public func removeRelated(_ id: String, _ related: String) async throws -> Product? {
        guard Bson.isObjectId(id) else { return nil }
        let change: BsonDocument = ["$pull": ["related": try Bson.ofObjectId(related)] as BsonDocument]
        let documentFilter: BsonDocument = ["_id": try Bson.ofObjectId(id)]
        return try await write { try await database.change("products", documentFilter, change) }.map(Product.from)
    }

    /// Runs a write; a database refusal (a unique value, a row still pointed to) becomes a conflict.
    private func write<T>(_ work: () async throws -> T) async throws -> T {
        do {
            return try await work()
        } catch let error where isRefusal(error) {
            throw DomainError.conflict(entity: "Product", reason: "the database refused the change: \(error)", fields: [])
        }
    }
}

/// Keeps products rows in memory, for tests and for trying the services without a database.
public final class MemoryProductRepository: ProductRepository {
    private let rows = MemoryRows<Product>()

    public init() {}

    /// The rows reads see, by primary key.
    private func visible() async -> [Product] {
        await rows.all.sorted(by: isBefore)
    }

    public func findById(_ id: String) async throws -> Product? {
        await visible().first { $0.id == id }
    }

    public func list(after: String?, limit: Int) async throws -> CursorPage<Product, String> {
        let rows = await visible().filter { row in after.map { isAfter(row, $0) } ?? true }
        let items = Array(rows.prefix(limit))
        return CursorPage(items: items, next: rows.count > limit ? items.last.map { $0.id! } : nil)
    }

    public func findBySku(_ sku: String) async throws -> Product? {
        await visible().first { $0.sku == sku }
    }

    public func findAllByTitle(_ title: String) async throws -> [Product] {
        await visible().filter { $0.title == title }
    }

    @discardableResult
    public func insert(_ entity: Product) async throws -> Product {
        var entity = entity
        entity.id = entity.id ?? Bson.newId()
        entity.stock = entity.stock ?? 0.0
        let row = entity
        await rows.store(row) { sameKey($0, row) }
        return row
    }

    @discardableResult
    public func update(_ entity: Product) async throws -> Product {
        await rows.store(entity) { sameKey($0, entity) }
        return entity
    }

    public func delete(_ entity: Product) async throws {
        await rows.remove { sameKey($0, entity) }
    }

    public func addRelated(_ id: String, _ related: String) async throws -> Product? {
        guard var found = await visible().first(where: { $0.id == id }) else { return nil }
        found.related = (found.related ?? []) + [related]
        let row = found
        await rows.store(row) { sameKey($0, row) }
        return row
    }

    public func removeRelated(_ id: String, _ related: String) async throws -> Product? {
        guard var found = await visible().first(where: { $0.id == id }) else { return nil }
        found.related?.removeAll { $0 == related }
        let row = found
        await rows.store(row) { sameKey($0, row) }
        return row
    }
}

/// Whether two rows have the same key.
fileprivate func sameKey(_ a: Product, _ b: Product) -> Bool {
    a.id == b.id
}

/// Whether a row comes before another, by primary key.
fileprivate func isBefore(_ a: Product, _ b: Product) -> Bool {
    return less(a.id, b.id)
}

/// Whether a row comes after a key.
fileprivate func isAfter(_ row: Product, _ key: String) -> Bool {
    return less(key, row.id)
}

