/// Operations on products. Each write runs in its own transaction.
public struct ProductService: Sendable {
    private let unitOfWork: any UnitOfWork

    public init(unitOfWork: any UnitOfWork) {
        self.unitOfWork = unitOfWork
    }

    /// Stores a new Product after checking it.
    @discardableResult
    public func createProduct(_ data: ProductCreate) async throws -> ProductRead {
        let values = Values(sku: data.sku.map(Optional.some), title: data.title.map(Optional.some), price: data.price.map(Optional.some), stock: data.stock.map(Optional.some), reference: data.reference.map(Optional.some), picture: data.picture.map(Optional.some), related: data.related.map(Optional.some))
        return try await unitOfWork.transaction { uow in
            try await checkValues(uow, values, nil)
            var entity = Product()
            applyValues(&entity, values)
            return try await read(uow.products.insert(entity))
        }
    }

    /// The Product with this key; notFound when there is none.
    public func getProduct(_ id: String) async throws -> ProductRead {
        try await read(find(unitOfWork, id))
    }

    /// A page of products after the key after (nil for the first page), by primary key.
    public func listProducts(after: String?, limit: Int) async throws -> CursorPage<ProductRead, String> {
        try await unitOfWork.products.list(after: after, limit: limit).map(read)
    }

    /// Changes the given values of a Product.
    @discardableResult
    public func updateProduct(_ id: String, _ changes: ProductUpdate) async throws -> ProductRead {
        let values = given(changes)
        return try await unitOfWork.transaction { uow in
            var current = try await find(uow, id)
            try await checkValues(uow, values, current)
            applyValues(&current, values)
            return try await read(uow.products.update(current))
        }
    }

    /// Deletes a Product.
    public func deleteProduct(_ id: String) async throws {
        try await unitOfWork.transaction { uow in
            let current = try await find(uow, id)
            try await uow.products.delete(current)
        }
    }

    /// The Product with this sku, or nil.
    public func findProductBySku(_ sku: String) async throws -> ProductRead? {
        try await unitOfWork.products.findBySku(sku).map(read)
    }

    /// Adds an item to related.
    @discardableResult
    public func addRelated(_ id: String, _ related: String) async throws -> ProductRead {
        return try await unitOfWork.transaction { uow in
            _ = try await find(uow, id)
            guard let changed = try await uow.products.addRelated(id, related) else {
                throw DomainError.notFound(entity: "Product", key: "\(id)")
            }
            return read(changed)
        }
    }

    /// Removes an item from related, by its value.
    @discardableResult
    public func removeRelated(_ id: String, _ related: String) async throws -> ProductRead {
        return try await unitOfWork.transaction { uow in
            let current = try await find(uow, id)
            if !(current.related ?? []).contains(related) {
                throw DomainError.notFound(entity: "Related", key: "\(related)")
            }
            guard let changed = try await uow.products.removeRelated(id, related) else {
                throw DomainError.notFound(entity: "Product", key: "\(id)")
