/// Rows for the tests: valid values for every column, and the rows they point to.
enum Factories {
    /// A valid Customer that is not stored yet; n makes its unique values differ.
    static func newCustomer(_ n: Int) -> Customer {
        Customer(email: "email-\(n)", name: "name-\(n)", passwordHash: "passwordhash-\(n)", active: true, level: "basic", address: newCustomerAddress(n), tags: [], preferences: newCustomerPreferences(n), extra: BsonValue(["n": n] as BsonDocument), updatedAt: Date(timeIntervalSince1970: TimeInterval(1_767_268_800 + (n % 28) * 86_400)))
    }

    /// A stored Customer.
    @discardableResult
    static func addCustomer(_ uow: any UnitOfWork, _ n: Int) async throws -> Customer {
        let entity = newCustomer(n)
        return try await uow.customers.insert(entity)
    }

    /// A valid Customer.Address; n makes its values differ.
    static func newCustomerAddress(_ n: Int) -> Customer.Address {
        Customer.Address(street: "street-\(n)", city: "city-\(n)", zipCode: "zipcode-\(n)", location: newCustomerAddressLocation(n))
    }

    /// A valid Customer.Address.Location; n makes its values differ.
    static func newCustomerAddressLocation(_ n: Int) -> Customer.Address.Location {
        Customer.Address.Location(type: "Point", coordinates: [])
    }

    /// A valid Customer.Preferences; n makes its values differ.
    static func newCustomerPreferences(_ n: Int) -> Customer.Preferences {
        Customer.Preferences(theme: "theme-\(n)", newsletter: true)
    }

    /// A valid Product that is not stored yet; n makes its unique values differ.
    static func newProduct(_ n: Int) -> Product {
        Product(sku: "sku-\(n)", title: "title-\(n)", price: Decimal(string: "\(n % 10000).50")!, stock: Double(n) + 0.5, reference: UUID(uuidString: String(format: "00000000-0000-4000-8000-%012d", n))!, picture: Data([UInt8(n % 256)]), related: [])
    }

    /// A stored Product.
    @discardableResult
    static func addProduct(_ uow: any UnitOfWork, _ n: Int) async throws -> Product {
        let entity = newProduct(n)
        return try await uow.products.insert(entity)
    }

    /// A valid Order that is not stored yet; n makes its unique values differ.
    static func newOrder(_ n: Int) -> Order {
        Order(number: Double(n) + 0.5, year: Double(n) + 0.5, lines: [newOrderLine(n)], notes: [newOrderNote(n)])
    }

    /// A stored Order, with the rows it points to.
    @discardableResult
    static func addOrder(_ uow: any UnitOfWork, _ n: Int) async throws -> Order {
        let parent0 = try await addCustomer(uow, n)
