        return try await uow.orders.insert(entity)
    }

    /// A valid Order.Line; n makes its values differ.
    static func newOrderLine(_ n: Int) -> Order.Line {
        Order.Line(product: String(format: "%024x", n), quantity: Double(1 + n) + 0.5, price: Decimal(string: "\(n % 10000).50")!, status: "pending")
