            let row = Factories.newProduct(1)
            let created = try await service.createProduct(createOf(row))
            try await service.deleteProduct(created.id)
            #expect(isNotFound(await refusal { try await service.getProduct(created.id) }))
        }

        @Test func addsAndRemovesOneItemOfRelated() async throws {
            let uow = MemoryUnitOfWork()
            let service = ProductService(unitOfWork: uow)
            let row = Factories.newProduct(1)
            let created = try await service.createProduct(createOf(row))
            let before = (created.related ?? []).count
            let n = 7
            let item = String(format: "%024x", n)
            let added = try await service.addRelated(created.id, item)
            #expect((added.related ?? []).count == before + 1)
            let removed = try await service.removeRelated(created.id, item)
            #expect((removed.related ?? []).count == before)
        }
    }
}

